      "tiers": [
        {
          "id": "practice.focus:t1",
          "title": "Голубь знает адрес",
          "phrase": "У тебя уже 5 разных дней с одним и тем же упражнением. Почтовый голубь одобряет: возвращаться по знакомому адресу — его тема.",
          "imagePrompt": "A carrier pigeon with chunky wristbands and one curled head feather lands on a compact exercise bench beside a single dumbbell. Its open wings balance the landing, while familiar claw marks trace the bench edge.",
          "fishMarkup": "[warm] У тебя уже 5 разных дней с одним и тем же упражнением. Почтовый голубь одобряет: возвращаться по знакомому адресу — <soft>его тема.</soft>",
          "audioText": "У тебя уже 5 разных дней с одним и тем же упражнением. Почтовый голубь одобряет: возвращаться по знакомому адресу — его тема."
        },
        {
          "id": "practice.focus:t2",
          "title": "Маршрут без пересадок",
          "phrase": "У тебя уже 15 разных дней с одним и тем же упражнением. Это не случайная встреча — у практики появился твой адрес.",
          "imagePrompt": "A carrier pigeon with chunky wristbands and one curled head feather confidently taxis down a tiny runway ending at its familiar exercise bench. A miniature windsock leans toward the dumbbell waiting on the seat.",
          "fishMarkup": "[confident] У тебя уже <emphasis>15 разных дней</emphasis> с одним и тем же упражнением. Это не случайная встреча — у практики появился твой адрес.",
          "audioText": "У тебя уже 15 разных дней с одним и тем же упражнением. Это не случайная встреча — у практики появился твой адрес."
        },
        {
          "id": "practice.focus:t3",
          "title": "Аэропорт одного упражнения",
          "phrase": "У тебя уже 30 разных дней с одним и тем же упражнением. Голубь постоянства открыл аэропорт — с рейсом «Опять сюда».",
          "imagePrompt": "A wristband-wearing carrier pigeon with a curled head feather lands beside its familiar dumbbell on an exercise bench. The bench is now an airport gate, with a tiny terminal underneath and a passenger jet absurdly queuing behind the bird.",
          "fishMarkup": "[triumphant] У тебя уже 30 разных дней с одним и тем же упражнением. [playful] Голубь постоянства открыл аэропорт — <slow>с рейсом «Опять сюда».</slow>",
          "audioText": "У тебя уже 30 разных дней с одним и тем же упражнением. Голубь постоянства открыл аэропорт — с рейсом «Опять сюда»."
        }
      ]
    },
    {
      "id": "practice.thousand_sets",
      "tiers": [
        {
          "id": "practice.thousand_sets:t1",
          "title": "Практика в переплёте",
          "phrase": "У тебя накопилось 400 подходов. История практики уже тянет на отдельный том — лень пока застряла в предисловии.",
          "imagePrompt": "A small octopus librarian in oversized reading glasses stacks thick exercise logbooks on a squat wheeled cart. One arm steadies the growing pile, another opens a fresh volume, and the remaining arms proudly present the little archive.",
          "fishMarkup": "[warm] У тебя накопилось 400 подходов. История практики уже тянет на отдельный том — <soft>лень пока застряла в предисловии.</soft>",
          "audioText": "У тебя накопилось 400 подходов. История практики уже тянет на отдельный том — лень пока застряла в предисловии."
        },
        {
          "id": "practice.thousand_sets:t2",
          "title": "Архив на восемь рук",
          "phrase": "Ты пополняешь историю практики: в ней уже 1000 подходов. Осьминог-библиотекарь задействовал все восемь рук.",
          "imagePrompt": "An octopus librarian in oversized reading glasses uses all eight arms to shelve hefty exercise logbooks along a sweeping spiral bookcase. Its wheeled cart waits below, piled high, while a small dumbbell props up the lowest row.",
          "fishMarkup": "[confident] Ты пополняешь историю практики: в ней уже <emphasis>1000 подходов.</emphasis> Осьминог-библиотекарь задействовал все восемь рук.",
          "audioText": "Ты пополняешь историю практики: в ней уже 1000 подходов. Осьминог-библиотекарь задействовал все восемь рук."
        },
        {
          "id": "practice.thousand_sets:t3",
          "title": "Аплодисменты с погрузчиком",
          "phrase": "У тебя накопилось 2500 подходов. Осьминог-библиотекарь аплодирует всеми восемью руками — а твою летопись держит погрузчик.",
          "imagePrompt": "An octopus librarian in oversized reading glasses applauds with four pairs of arms beside its tiny abandoned book cart. Behind it, a forklift hoists an enormous exercise logbook, its thick page block towering over the delighted librarian.",
          "fishMarkup": "[triumphant] У тебя накопилось 2500 подходов. [playful] Осьминог-библиотекарь аплодирует всеми восемью руками — <slow>а твою летопись держит погрузчик.</slow>",
          "audioText": "У тебя накопилось 2500 подходов. Осьминог-библиотекарь аплодирует всеми восемью руками — а твою летопись держит погрузчик."
        }
      ]
    }
  ]
